.evx_null_cache <- new.env(parent = emptyenv())

#' Shared null sample used by the Python simulation notebook
#'
#' @param n Number of null statistics to return, between 2 and 100000.
#'   The default returns the complete sample used in the paper notebook.
#' @return A numeric vector of null t statistics with one degree of freedom.
#' @details The bundled sample was generated by the repository's Python
#'   simulation notebook from 100000 independent pairs of standard normal
#'   observations using NumPy's default_rng with seed 20260510. It is stored
#'   in original sampling order. This function reads those actual draws;
#'   using the same numeric seed in R would not reproduce NumPy's stream.
#'   Requesting fewer draws returns a prefix. No R random-number state is
#'   changed. Reuse the same vector across priors with [ev_calibration()].
#'   These finite Monte Carlo draws approximate the population calibration.
#' @seealso [ev_calibration()], [ev_ttest()]
#' @export
ev_null_sample <- function(n = 100000L) {
  if (!is.numeric(n) || length(n) != 1L || !is.finite(n) ||
      n < 2 || n > 100000 || n != as.integer(n)) {
    stop("`n` must be an integer between 2 and 100000.", call. = FALSE)
  }
  if (!exists("sample", .evx_null_cache, inherits = FALSE)) {
    filename <- "python_null_t_seed20260510.csv.gz"
    path <- system.file("extdata", filename, package = "eVille")
    if (!nzchar(path)) {
      stop("The bundled null sample was not found; reinstall eVille or supply `null_t`.",
           call. = FALSE)
    }
    sample <- utils::read.csv(path)[[1L]]
    if (length(sample) != 100000L || any(!is.finite(sample))) {
      stop("The bundled null sample is incomplete or invalid.", call. = FALSE)
    }
    assign("sample", as.numeric(sample), .evx_null_cache)
  }
  get("sample", .evx_null_cache, inherits = FALSE)[seq_len(n)]
}
